insert into profile (id, name, headline, bio, github_url) values (
  1,
  'sasukeaizen7',
  'Data engineer: pipelines, warehouses and streaming, on real public data',
  'Eleven data engineering projects and 18 SQL analytics projects built over a 100-day program, from a Python ETL to a live, monitored pipeline. Everything runs locally with Docker and is checked by CI on every push.',
